     1→/**
     2→ * FreeLang Nexus - 통합 Lexer
     3→ * V 모드 + Python 모드를 동시에 지원
     4→ *
     5→ * PyFree의 INDENT/DEDENT 패턴 + FV의 복합 연산자 처리 + 모드 전환
     6→ */
     7→
     8→import {
     9→  Token,
    10→  TokenType,
    11→  getKeywordToken,
    12→  detectMode,
    13→  V_KEYWORDS,
    14→  PYTHON_KEYWORDS,
    15→} from './token';
    16→import { ModeDetector } from './mode-detector';
    17→
    18→export class NexusLexer {
    19→  private source: string;
    20→  private pos: number = 0;
    21→  private line: number = 1;
    22→  private column: number = 1;
    23→  private currentMode: 'v' | 'python' | 'auto' = 'auto';
    24→  private indentStack: number[] = [0]; // Python INDENT/DEDENT 스택 (PyFree 패턴)
    25→  private atLineStart: boolean = true; // Python 들여쓰기 처리용
    26→  private tokens: Token[] = [];
    27→
    28→  constructor(source: string) {
    29→    this.source = source;
    30→  }
    31→
    32→  /**
    33→   * 전체 소스 토큰화
    34→   */
    35→  tokenize(): Token[] {
    36→    while (this.pos < this.source.length) {
    37→      const token = this.nextToken();
    38→      if (token) {
    39→        this.tokens.push(token);
    40→      }
    41→    }
    42→
    43→    // EOF 토큰 추가
    44→    this.tokens.push(this.makeToken(TokenType.EOF, '', this.currentMode));
    45→
    46→    return this.tokens;
    47→  }
    48→
    49→  /**
    50→   * 다음 토큰 가져오기
    51→   */
    52→  private nextToken(): Token | null {
    53→    const ch = this.peek();
    54→
    55→    if (ch === undefined) {
    56→      return null;
    57→    }
    58→
    59→    // 개행
    60→    if (ch === '\n') {
    61→      this.advance();
    62→      this.atLineStart = true;
    63→      this.column = 1;
    64→      return this.makeToken(TokenType.NEWLINE, '\n', this.currentMode);
    65→    }
    66→
    67→    // 줄 시작에서 들여쓰기 처리 (Python 모드)
    68→    if (this.atLineStart && this.currentMode === 'python') {
    69→      const indentToken = this.handleIndentation();
    70→      this.atLineStart = false;
    71→      if (indentToken) {
    72→        return indentToken;
    73→      }
    74→    }
    75→
    76→    // 공백 (탭, 스페이스) - 이미 라인 시작 처리됨
    77→    if (this.isWhitespace(ch)) {
    78→      this.skipWhitespace();
    79→      return this.nextToken(); // 재귀 호출
    80→    }
    81→
    82→    // 주석: V 모드는 //, Python 모드는 #
    83→    if (ch === '/' && this.peek(1) === '/' && this.currentMode === 'v') {
    84→      this.skipLineComment();
    85→      return this.nextToken(); // 재귀 호출
    86→    }
    87→
    88→    if (ch === '#' && this.currentMode === 'python') {
    89→      this.skipLineComment();
    90→      return this.nextToken(); // 재귀 호출
    91→    }
    92→
    93→    // @mode 디렉티브
    94→    if (ch === '@') {
    95→      const modeToken = this.tryParseMode();
    96→      if (modeToken) {
    97→        return modeToken;
    98→      }
    99→    }
   100→
   101→    // 문자열
   102→    if (ch === '"' || ch === "'" || (ch === 'f' && (this.peek(1) === '"' || this.peek(1) === "'"))) {
   103→      return this.tokenizeString();
   104→    }
   105→
   106→    // 숫자
   107→    if (this.isDigit(ch)) {
   108→      return this.tokenizeNumber();
   109→    }
   110→
   111→    // 식별자 또는 키워드
   112→    if (this.isIdentifierStart(ch)) {
   113→      return this.tokenizeIdentifierOrKeyword();
   114→    }
   115→
   116→    // 연산자
   117→    const operatorToken = this.tokenizeOperator();
   118→    if (operatorToken) {
   119→      return operatorToken;
   120→    }
   121→
   122→    // 알 수 없는 문자
   123→    throw new Error(`Unknown character: '${ch}' at line ${this.line}, column ${this.column}`);
   124→  }
   125→
   126→  /**
   127→   * 들여쓰기 처리 (Python 모드 전용)
   128→   * PyFree 패턴 재사용
   129→   */
   130→  private handleIndentation(): Token | null {
   131→    let indent = 0;
   132→
   133→    // 현재 위치에서 연속된 스페이스/탭 세기 (이미 라인 시작에 있다고 가정)
   134→    const lineStart = this.pos;
   135→    while (this.pos < this.source.length) {
   136→      const ch = this.peek();
   137→      if (ch === ' ') {
   138→        indent += 1;
   139→        this.pos++;
   140→      } else if (ch === '\t') {
   141→        indent += 8; // 탭 = 8 스페이스
   142→        this.pos++;
   143→      } else {
   144→        break;
   145→      }
   146→    }
   147→
   148→    // 라인이 비어있으면 (주석/개행만) 들여쓰기 무시
   149→    const ch = this.peek();
   150→    if (ch === '\n' || ch === '#' || ch === undefined) {
   151→      this.pos = lineStart;
   152→      return null;
   153→    }
   154→
   155→    const currentIndent = this.indentStack[this.indentStack.length - 1] || 0;
   156→
   157→    if (indent > currentIndent) {
   158→      // INDENT
   159→      this.indentStack.push(indent);
   160→      return this.makeToken(TokenType.INDENT, '\t', this.currentMode);
   161→    } else if (indent < currentIndent) {
   162→      // DEDENT
   163→      while (this.indentStack.length > 0 && this.indentStack[this.indentStack.length - 1] > indent) {
   164→        this.indentStack.pop();
   165→      }
   166→      return this.makeToken(TokenType.DEDENT, '', this.currentMode);
   167→    }
   168→
   169→    return null;
   170→  }
   171→
   172→  /**
   173→   * 식별자 또는 키워드 토큰화
   174→   */
   175→  private tokenizeIdentifierOrKeyword(): Token {
   176→    const start = this.pos;
   177→    const startColumn = this.column;
   178→
   179→    while (this.pos < this.source.length && this.isIdentifierChar(this.peek())) {
   180→      this.advance();
   181→    }
   182→
   183→    const value = this.source.substring(start, this.pos);
   184→
   185→    // 키워드 확인
   186→    const keywordType = getKeywordToken(value, this.currentMode);
   187→    if (keywordType) {
   188→      return this.makeToken(keywordType, value, this.currentMode);
   189→    }
   190→
   191→    return this.makeToken(TokenType.IDENTIFIER, value, this.currentMode);
   192→  }
   193→
   194→  /**
   195→   * 숫자 토큰화
   196→   */
   197→  private tokenizeNumber(): Token {
   198→    const start = this.pos;
   199→
   200→    // 16진수 (0x)
   201→    if (this.peek() === '0' && (this.peek(1) === 'x' || this.peek(1) === 'X')) {
   202→      this.advance(); // '0'
   203→      this.advance(); // 'x'
   204→      while (this.isHexDigit(this.peek())) {
   205→        this.advance();
   206→      }
   207→    }
   208→    // 2진수 (0b)
   209→    else if (this.peek() === '0' && (this.peek(1) === 'b' || this.peek(1) === 'B')) {
   210→      this.advance(); // '0'
   211→      this.advance(); // 'b'
   212→      while (this.peek() === '0' || this.peek() === '1') {
   213→        this.advance();
   214→      }
   215→    }
   216→    // 8진수 (0o)
   217→    else if (this.peek() === '0' && (this.peek(1) === 'o' || this.peek(1) === 'O')) {
   218→      this.advance(); // '0'
   219→      this.advance(); // 'o'
   220→      while (this.isOctalDigit(this.peek())) {
   221→        this.advance();
   222→      }
   223→    }
   224→    // 10진수 (정수 또는 실수)
   225→    else {
   226→      while (this.isDigit(this.peek())) {
   227→        this.advance();
   228→      }
   229→
   230→      // 실수: . 또는 e/E
   231→      if (this.peek() === '.' && this.isDigit(this.peek(1))) {
   232→        this.advance(); // '.'
   233→        while (this.isDigit(this.peek())) {
   234→          this.advance();
   235→        }
   236→      }
   237→
   238→      if (this.peek() === 'e' || this.peek() === 'E') {
   239→        this.advance();
   240→        if (this.peek() === '+' || this.peek() === '-') {
   241→          this.advance();
   242→        }
   243→        while (this.isDigit(this.peek())) {
   244→          this.advance();
   245→        }
   246→      }
   247→    }
   248→
   249→    const value = this.source.substring(start, this.pos);
   250→    return this.makeToken(TokenType.NUMBER, value, this.currentMode);
   251→  }
   252→
   253→  /**
   254→   * 문자열 토큰화
   255→   */
   256→  private tokenizeString(): Token {
   257→    const start = this.pos;
   258→    let isFString = false;
   259→
   260→    // f-string 확인
   261→    if (this.peek() === 'f' && (this.peek(1) === '"' || this.peek(1) === "'")) {
   262→      isFString = true;
   263→      this.advance(); // 'f'
   264→    }
   265→
   266→    const quote = this.peek();
   267→    this.advance(); // 첫 따옴표
   268→
   269→    // 3중 따옴표 확인
   270→    let isTriple = false;
   271→    if (this.peek() === quote && this.peek(1) === quote) {
   272→      isTriple = true;
   273→      this.advance();
   274→      this.advance();
   275→    }
   276→
   277→    // 문자열 내용 읽기
   278→    while (this.pos < this.source.length) {
   279→      const ch = this.peek();
   280→
   281→      if (isTriple) {
   282→        if (ch === quote && this.peek(1) === quote && this.peek(2) === quote) {
   283→          this.advance();
   284→          this.advance();
   285→          this.advance();
   286→          break;
   287→        }
   288→      } else {
   289→        if (ch === quote) {
   290→          this.advance();
   291→          break;
   292→        }
   293→        if (ch === '\n') {
   294→          throw new Error(`Unterminated string at line ${this.line}`);
   295→        }
   296→      }
   297→
   298→      if (ch === '\\') {
   299→        this.advance(); // 이스케이프 문자 다음
   300→        if (this.pos < this.source.length) {
   301→          this.advance();
   302→        }
   303→      } else {
   304→        this.advance();
   305→      }
   306→    }
   307→
   308→    const value = this.source.substring(start, this.pos);
   309→    return this.makeToken(TokenType.STRING, value, this.currentMode);
   310→  }
   311→
   312→  /**
   313→   * 연산자 토큰화
   314→   */
   315→  private tokenizeOperator(): Token | null {
   316→    const ch = this.peek();
   317→    const next = this.peek(1);
   318→    const next2 = this.peek(2);
   319→
   320→    // 3글자 연산자
   321→    if (ch === '.' && next === '.' && next2 === '=') {
   322→      this.advance();
   323→      this.advance();
   324→      this.advance();
   325→      return this.makeToken(TokenType.IDENTIFIER, '..=', this.currentMode); // 커스텀
   326→    }
   327→
   328→    // 2글자 연산자
   329→    const twoChar = ch && next ? ch + next : '';
   330→    const twoCharMap: Record<string, TokenType> = {
   331→      '->': TokenType.ARROW,
   332→      '=>': TokenType.IDENTIFIER, // FatArrow (커스텀)
   333→      '==': TokenType.EQ,
   334→      '!=': TokenType.NE,
   335→      '<=': TokenType.LE,
   336→      '>=': TokenType.GE,
   337→      '&&': TokenType.AND,
   338→      '||': TokenType.OR,
   339→      '::': TokenType.IDENTIFIER, // DoubleColon (커스텀)
   340→      '..': TokenType.IDENTIFIER, // DotDot (커스텀)
   341→      '//': TokenType.SLASH, // 이미 주석 처리됨
   342→      '**': TokenType.STAR, // Power (커스텀)
   343→    };
   344→
   345→    if (twoCharMap[twoChar]) {
   346→      this.advance();
   347→      this.advance();
   348→      return this.makeToken(twoCharMap[twoChar], twoChar, this.currentMode);
   349→    }
   350→
   351→    // 1글자 연산자
   352→    const oneCharMap: Record<string, TokenType> = {
   353→      '(': TokenType.LPAREN,
   354→      ')': TokenType.RPAREN,
   355→      '{': TokenType.LBRACE,
   356→      '}': TokenType.RBRACE,
   357→      '[': TokenType.LBRACKET,
   358→      ']': TokenType.RBRACKET,
   359→      ',': TokenType.COMMA,
   360→      '.': TokenType.DOT,
   361→      ';': TokenType.SEMICOLON,
   362→      ':': TokenType.COLON,
   363→      '=': TokenType.EQUAL,
   364→      '+': TokenType.PLUS,
   365→      '-': TokenType.MINUS,
   366→      '*': TokenType.STAR,
   367→      '/': TokenType.SLASH,
   368→      '%': TokenType.PERCENT,
   369→      '<': TokenType.LT,
   370→      '>': TokenType.GT,
   371→      '!': TokenType.NOT,
   372→      '&': TokenType.AMPERSAND,
   373→      '|': TokenType.PIPE,
   374→      '@': TokenType.AT,
   375→    };
   376→
   377→    if (ch && oneCharMap[ch]) {
   378→      this.advance();
   379→      return this.makeToken(oneCharMap[ch], ch, this.currentMode);
   380→    }
   381→
   382→    return null;
   383→  }
   384→
   385→  /**
   386→   * @mode() 디렉티브 파싱
   387→   */
   388→  private tryParseMode(): Token | null {
   389→    const start = this.pos;
   390→
   391→    if (this.peek() !== '@') {
   392→      return null;
   393→    }
   394→
   395→    this.advance(); // '@'
   396→
   397→    // @mode 확인
   398→    if (
   399→      this.peek() === 'm' &&
   400→      this.peek(1) === 'o' &&
   401→      this.peek(2) === 'd' &&
   402→      this.peek(3) === 'e'
   403→    ) {
   404→      this.advance();
   405→      this.advance();
   406→      this.advance();
   407→      this.advance();
   408→
   409→      // 공백 및 ( 확인
   410→      while (this.isWhitespace(this.peek()) && this.peek() !== '\n') {
   411→        this.advance();
   412→      }
   413→
   414→      if (this.peek() !== '(') {
   415→        // @mode가 아니면 다시 돌아가기
   416→        this.pos = start;
   417→        return null;
   418→      }
   419→
   420→      this.advance(); // '('
   421→
   422→      // 공백
   423→      while (this.isWhitespace(this.peek()) && this.peek() !== '\n') {
   424→        this.advance();
   425→      }
   426→
   427→      // v 또는 python 확인
   428→      let mode: 'v' | 'python' | null = null;
   429→
   430→      if (this.peek() === 'v' && (this.peek(1) === ')' || this.isWhitespace(this.peek(1)))) {
   431→        mode = 'v';
   432→        this.advance();
   433→      } else if (
   434→        this.peek() === 'p' &&
   435→        this.peek(1) === 'y' &&
   436→        this.peek(2) === 't' &&
   437→        this.peek(3) === 'h' &&
   438→        this.peek(4) === 'o' &&
   439→        this.peek(5) === 'n'
   440→      ) {
   441→        mode = 'python';
   442→        this.advance();
   443→        this.advance();
   444→        this.advance();
   445→        this.advance();
   446→        this.advance();
   447→        this.advance();
   448→      }
   449→
   450→      if (!mode) {
   451→        // 유효한 모드가 아니면 다시 돌아가기
   452→        this.pos = start;
   453→        return null;
   454→      }
   455→
   456→      // 공백 및 ) 확인
   457→      while (this.isWhitespace(this.peek()) && this.peek() !== '\n') {
   458→        this.advance();
   459→      }
   460→
   461→      if (this.peek() !== ')') {
   462→        this.pos = start;
   463→        return null;
   464→      }
   465→
   466→      this.advance(); // ')'
   467→
   468→      // 모드 전환!
   469→      this.currentMode = mode;
   470→
   471→      const value = this.source.substring(start, this.pos);
   472→      return this.makeToken(TokenType.MODE_MARKER, value, mode);
   473→    }
   474→
   475→    this.pos = start;
   476→    return null;
   477→  }
   478→
   479→  // ==================== 헬퍼 함수 ====================
   480→
   481→  private skipWhitespaceOnLineStart(): void {
   482→    // 라인 시작의 공백 스킵
   483→    while (this.pos < this.source.length) {
   484→      const ch = this.peek();
   485→      if (ch === ' ' || ch === '\t') {
   486→        this.advance();
   487→      } else if (ch === '\n') {
   488→        this.advance();
   489→        this.atLineStart = true;
   490→      } else {
   491→        break;
   492→      }
   493→    }
   494→  }
   495→
   496→  private skipWhitespace(): void {
   497→    while (this.pos < this.source.length && this.isWhitespace(this.peek())) {
   498→      this.advance();
   499→    }
   500→  }
   501→
   502→  private skipLineComment(): void {
   503→    while (this.pos < this.source.length && this.peek() !== '\n') {
   504→      this.advance();
   505→    }
   506→  }
   507→
   508→  private peek(offset: number = 0): string | undefined {
   509→    return this.source[this.pos + offset];
   510→  }
   511→
   512→  private advance(): void {
   513→    const ch = this.peek();
   514→    if (ch === '\n') {
   515→      this.line++;
   516→      this.column = 1;
   517→    } else {
   518→      this.column++;
   519→    }
   520→    this.pos++;
   521→  }
   522→
   523→  private isWhitespace(ch: string | undefined): boolean {
   524→    return ch === ' ' || ch === '\t' || ch === '\r' || ch === '\n';
   525→  }
   526→
   527→  private isDigit(ch: string | undefined): boolean {
   528→    return ch !== undefined && ch >= '0' && ch <= '9';
   529→  }
   530→
   531→  private isHexDigit(ch: string | undefined): boolean {
   532→    return (
   533→      ch !== undefined &&
   534→      ((ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F'))
   535→    );
   536→  }
   537→
   538→  private isOctalDigit(ch: string | undefined): boolean {
   539→    return ch !== undefined && ch >= '0' && ch <= '7';
   540→  }
   541→
   542→  private isIdentifierStart(ch: string | undefined): boolean {
   543→    return (
   544→      ch !== undefined &&
   545→      ((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || ch === '_' || ch === '$')
   546→    );
   547→  }
   548→
   549→  private isIdentifierChar(ch: string | undefined): boolean {
   550→    return this.isIdentifierStart(ch) || this.isDigit(ch);
   551→  }
   552→
   553→  private makeToken(
   554→    type: TokenType,
   555→    value: string,
   556→    mode: 'v' | 'python' | 'auto'
   557→  ): Token {
   558→    return {
   559→      type,
   560→      value,
   561→      line: this.line,
   562→      column: this.column - value.length,
   563→      mode,
   564→      startPos: this.pos - value.length,
   565→      endPos: this.pos,
   566→    };
   567→  }
   568→}
   569→
   570→export default NexusLexer;
   571→

