     1→/**
     2→ * PyFree AST (Abstract Syntax Tree) 정의
     3→ * Python + FreeLang 통합 구문을 표현
     4→ *
     5→ * 구조:
     6→ * - 프로그램 레벨
     7→ * - 문장 (Statements)
     8→ * - 표현식 (Expressions)
     9→ * - 타입 (Type Annotations)
    10→ * - 데코레이터
    11→ */
    12→
    13→/**
    14→ * 기본 AST 노드 인터페이스
    15→ */
    16→export interface ASTNode {
    17→  type: string;
    18→  line: number;
    19→  column: number;
    20→}
    21→
    22→/**
    23→ * 프로그램 루트
    24→ */
    25→export interface Program extends ASTNode {
    26→  type: 'Program';
