   750→  /**
   751→   * Import 파싱
   752→   * ✅ Phase 15: 점(.) 포함 모듈 경로 지원
   753→   */
   754→  private parseImportStatement(): AST.ImportStatement {
   755→    const startToken = this.peek();
   756→    let isFromImport = false;
   757→    let module: string | undefined;
   758→
   759→    if (this.match(TokenType.FROM)) {
   760→      isFromImport = true;
   761→      // 점 포함 경로 수집: os, os.path, collections.abc 등
   762→      let moduleParts = [this.consume(TokenType.IDENTIFIER, '모듈명 필요').value];
