   772→    const names: AST.ImportName[] = [];
   773→    do {
   774→      let nameParts = [this.consume(TokenType.IDENTIFIER, '이름 필요').value];
   775→      if (!isFromImport) {
   776→        // import 문에서는 점 경로 지원 (import os.path as ospath)
   777→        while (this.match(TokenType.DOT)) {
   778→          nameParts.push(this.consume(TokenType.IDENTIFIER, '모듈 경로 필요').value);
   779→        }
