   781→      const name = nameParts.join('.');
   782→      let asName: string | undefined;
   783→      if (this.match(TokenType.AS)) {
   784→        asName = this.consume(TokenType.IDENTIFIER, '별칭명 필요').value;
   785→      }
   786→      names.push({ name, asName });
